import httpximport pytestimport respxfrom fastapi.testclient import TestClientfrom pydantic import ValidationErrorfrom app.config import Settings, get_settingsfrom app.main import appfrom app.platforms.base import SocialPlatformfrom app.schemas import PostRequestfrom app.services.posting_service import PostingServicedef test_post_request_validation_valid():    """Valid message with exactly one URL passes validation."""    req = PostRequest(message="Check out this cool site https://example.com")    assert req.message is not Nonedef test_post_request_validation_too_long():    """Message over 200 characters fails validation."""    long_msg = "A" * 190 + " https://example.com"    with pytest.raises(ValidationError) as exc_info:        PostRequest(message=long_msg)    assert "at most 200 characters" in str(exc_info.value)def test_post_request_validation_no_url():    """Message without any URL fails validation."""    with pytest.raises(ValidationError) as exc_info:        PostRequest(message="Hello world without any link here")    assert "Message must contain a URL" in str(exc_info.value)def test_post_request_validation_multiple_urls():    """Message with multiple URLs fails validation."""    with pytest.raises(ValidationError) as exc_info:        PostRequest(message="Visit https://example.com and https://test.com")    assert "exactly one URL, found multiple" in str(exc_info.value)def test_post_request_validation_bad_url():    """Message with invalid URL format fails validation."""    with pytest.raises(ValidationError) as exc_info:        PostRequest(message="Check this out not-a-url")    assert "Message must contain a URL" in str(exc_info.value)class FakeSuccessPlatform(SocialPlatform):    @property    def name(self) -> str:        return "FakeSuccess"    @property    def required_credentials(self) -> list[str]:        return []    async def _publish(self, message: str) -> str:        return "https://fakesuccess.com/post/1"class FakeFailurePlatform(SocialPlatform):    @property    def name(self) -> str:        return "FakeFailure"    @property    def required_credentials(self) -> list[str]:        return []    async def _publish(self, message: str) -> str:        request = httpx.Request("POST", "https://example.com")        response = httpx.Response(400, text="API error", request=request)        raise httpx.HTTPStatusError("API error", request=request, response=response)class FakeExceptionPlatform(SocialPlatform):    @property    def name(self) -> str:        return "FakeException"    @property    def required_credentials(self) -> list[str]:        return []    async def _publish(self, message: str) -> str:        raise RuntimeError("Network timeout")@pytest.mark.asyncioasync def test_posting_service_resilience():    """Ensure service handles success, failure, and exceptions without stopping others."""    platforms = [        FakeSuccessPlatform(None),  # type: ignore        FakeFailurePlatform(None),  # type: ignore        FakeExceptionPlatform(None),  # type: ignore    ]    service = PostingService(platforms)    response = await service.post_to_all("Test message https://example.com")    assert response.success is True    assert len(response.results) == 3    success_res = next(r for r in response.results if r.platform == "FakeSuccess")    assert success_res.status == "success"    assert success_res.posted_url == "https://fakesuccess.com/post/1"    fail_res = next(r for r in response.results if r.platform == "FakeFailure")    assert fail_res.status == "failure"    assert "HTTP error 400" in (fail_res.error or "")    exc_res = next(r for r in response.results if r.platform == "FakeException")    assert exc_res.status == "failure"    assert "Network timeout" in (exc_res.error or "")@respx.mockdef test_e2e_posting_mixed_success_failure():    """Test POST /posting endpoint with 2 platforms succeeding and 3 failing."""    respx.post("https://api.telegram.org/bot_test_token/sendMessage").mock(        return_value=httpx.Response(            200, json={"ok": True, "result": {"message_id": 100}}        )    )    respx.post("https://mastodon.social/api/v1/statuses").mock(        return_value=httpx.Response(            200, json={"url": "https://mastodon.social/@user/500"}        )    )    respx.post("https://dev.to/api/articles").mock(        return_value=httpx.Response(401, text="Unauthorized")    )    respx.post("https://api.github.com/gists").mock(        side_effect=httpx.TimeoutException("Timeout")    )    respx.post("https://pastebin.com/api/api_post.php").mock(        return_value=httpx.Response(200, text="Bad API request")    )    def override_get_settings():        return Settings(            telegram_bot_token="_test_token",            telegram_channel="@channel",            mastodon_base_url="https://mastodon.social",            mastodon_access_token="mastodon_token",            devto_api_key="devto_key",            github_token="github_token",            pastebin_api_dev_key="pastebin_key",        )    app.dependency_overrides[get_settings] = override_get_settings    try:        with TestClient(app) as test_client:            response = test_client.post(                "/posting", json={"message": "Hello world https://example.com"}            )            assert response.status_code == 200            data = response.json()            assert data["success"] is True            assert len(data["results"]) == 5            success_count = sum(1 for r in data["results"] if r["status"] == "success")            failure_count = sum(1 for r in data["results"] if r["status"] == "failure")            assert success_count == 2            assert failure_count == 3    finally:        app.dependency_overrides.clear()def test_health_endpoint():    """Test health check endpoint."""    with TestClient(app) as test_client:        response = test_client.get("/health")        assert response.status_code == 200        assert response.json() == {"status": "ok"}